/**
 * Bulk-safe handler for ContactTrigger.
 *
 * Trigger contexts: before insert, before update, after insert.
 *
 * Governor budget per batch (up to 200 contacts), before + after combined:
 *   - SOQL queries: at most 2 (one in the before context, one in the after context)
 *   - DML statements: at most 1 (one bulk Account update in the after context)
 *
 * Sharing is inherited from the DML operation, exactly as with the original
 * trigger (no with/without sharing modifier).
 */
public class ContactTriggerHandler {

    /**
     * Single entry point called from ContactTrigger. Contains all SOQL/DML,
     * the trigger itself stays empty of queries and DML.
     */
    public static void onExecute() {
        if (Trigger.isBefore) {
            handleBeforeInsertOrUpdate();
        }
        if (Trigger.isAfter && Trigger.isInsert) {
            handleAfterInsert();
        }
    }

    /**
     * Before insert / before update.
     *
     * For each contact that has an AccountId:
     *  - MailingCountry is filled from the Account's BillingCountry when blank
     *    (insert and update),
     *  - LeadSource is filled from the Account's AccountSource when blank
     *    (insert only, as in the original trigger).
     *
     * Uses a single SOQL to load all referenced accounts for the whole batch.
     */
    private static void handleBeforeInsertOrUpdate() {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : Trigger.new) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        // SOQL query 1 of the batch: all referenced accounts in one shot
        Map<Id, Account> accountMap = new Map<Id, Account>(
            [SELECT BillingCountry, AccountSource FROM Account WHERE Id IN :accountIds]
        );

        for (Contact c : Trigger.new) {
            if (c.AccountId == null) {
                continue;
            }
            Account a = accountMap.get(c.AccountId);
            if (a == null) {
                continue;
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }
            if (Trigger.isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }

    /**
     * After insert.
     *
     * When an Account's Phone is blank, it inherits the phone of the first
     * new contact (in trigger order) that has a phone. This preserves the
     * original behaviour where the first such contact in the batch set the
     * account phone and every later contact of the same account was skipped.
     *
     * Uses one SOQL (query 2 of the batch) and at most one bulk DML statement.
     */
    private static void handleAfterInsert() {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : Trigger.new) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        // SOQL query 2 of the batch: current phone of every referenced account
        Map<Id, Account> accountMap = new Map<Id, Account>(
            [SELECT Id, Phone FROM Account WHERE Id IN :accountIds]
        );

        List<Account> accountsToUpdate = new List<Account>();
        for (Contact c : Trigger.new) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }
            Account a = accountMap.get(c.AccountId);
            if (a == null || !String.isBlank(a.Phone)) {
                // Account missing, or already has a phone (including one
                // just set by an earlier contact in this batch).
                continue;
            }
            a.Phone = c.Phone; // first contact in trigger order wins
            accountsToUpdate.add(a);
        }

        if (!accountsToUpdate.isEmpty()) {
            // DML 1 of the batch: single bulk update of all affected accounts
            update accountsToUpdate;
        }
    }
}
