/**
 * LogPurgeJob
 *
 * Nightly maintenance job that purges old FB_Integration_Log__c records to
 * reclaim storage:
 *   - Non-ERROR logs (including blank levels) are deleted once they are more
 *     than 30 days old.
 *   - ERROR logs are retained longer and deleted once they are more than 180
 *     days old.
 *
 * Deletions are performed in bounded batches (semi-automatic bulk DML) so the
 * job stays safe even when the object holds large volumes of old records.
 */
public class LogPurgeJob implements Schedulable {

    /** Largest batch a SOQL query can return; also keeps DML statements bounded. */
    private static final Integer BATCH_SIZE = 50000;
    private static final String ERROR_LEVEL = 'ERROR';
    private static final Integer NON_ERROR_RETENTION_DAYS = 30;
    private static final Integer ERROR_RETENTION_DAYS = 180;

    public LogPurgeJob() {
    }

    /**
     * Called by the scheduler on each run.
     */
    public void execute(SchedulableContext context) {
        Datetime nonErrorCutoff = Datetime.now().addDays(-NON_ERROR_RETENTION_DAYS);
        Datetime errorCutoff = Datetime.now().addDays(-ERROR_RETENTION_DAYS);

        // Delete non-ERROR logs (Level__c blank or any value other than ERROR)
        // that are older than 30 days.
        List<FB_Integration_Log__c> batch;
        do {
            batch = [
                SELECT Id
                FROM FB_Integration_Log__c
                WHERE CreatedDate < :nonErrorCutoff
                AND (Level__c = NULL OR Level__c != :ERROR_LEVEL)
                LIMIT :BATCH_SIZE
            ];
            if (!batch.isEmpty()) {
                DELETE batch;
            }
        } while (!batch.isEmpty());

        // Delete ERROR logs that are older than 180 days.
        do {
            batch = [
                SELECT Id
                FROM FB_Integration_Log__c
                WHERE CreatedDate < :errorCutoff
                AND Level__c = :ERROR_LEVEL
                LIMIT :BATCH_SIZE
            ];
            if (!batch.isEmpty()) {
                DELETE batch;
            }
        } while (!batch.isEmpty());
    }

    /**
     * Schedules the job to run every day at 02:00 (org timezone) under the
     * name 'Log purge (nightly)' and returns the job Id.
     */
    public static Id scheduleNightly() {
        String cronExpression = '0 2 0 * * ?'; // 02:00:00 daily
        return System.schedule('Log purge (nightly)', cronExpression, new LogPurgeJob());
    }
}
