/**
 * @description
 * Domain class for the Opportunity SObject.
 *
 * Validation rules:
 * 1. Amount must not be negative (on insert and on update).
 * 2. The Amount of an opportunity that was already Closed Won before the
 *    update cannot be changed (closing it as won and changing the amount
 *    in the same update is allowed).
 */
public class Opportunities extends fflib_SObjectDomain {

    // Constructor

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public Constructor() {
        }

        public Object construct(Object context) {
            return new Opportunities();
        }

        public void validateConstructor() {
        }
    }

    public Opportunities() {
    }

    // Trigger handlers

    protected override void onBeforeInsert(List<SObject> newRecords) {
        List<Opportunity> records = (List<Opportunity>) newRecords;
        for (Opportunity record : records) {
            if (record.Amount != null && record.Amount < 0) {
                error('Amount cannot be negative.', record, 'Amount');
            }
        }
    }

    protected override void onBeforeUpdate(List<SObject> oldRecords, List<SObject> newRecords) {
        List<Opportunity> oldRecs = (List<Opportunity>) oldRecords;
        List<Opportunity> newRecs = (List<Opportunity>) newRecords;
        for (Integer i = 0; i < newRecs.size(); i++) {
            Opportunity oldRec = oldRecs[i];
            Opportunity newRec = newRecs[i];

            if (newRec.Amount != null && newRec.Amount < 0) {
                error('Amount cannot be negative.', newRec, 'Amount');
            }

            if (oldRec.Stage == 'Closed Won' && newRec.Amount != oldRec.Amount) {
                error('Amount cannot change on a won opportunity.', newRec, 'Amount');
            }
        }
    }
}
