/**
 * Normalizes Contact phone numbers for the new dialer, which only accepts
 * digits and a leading plus sign.
 */
public class ContactPhoneCleanup {

    /**
     * Strips every non-digit / non-'+' character from the Phone field of the
     * given contacts and saves the changes in one bulk DML call.
     *
     * @param contactIds up to 200 Contact Ids
     * @return map of the Id of each contact that could not be saved to its first
     *         error message. Empty map when everything was saved (or there was
     *         nothing to save).
     */
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> failures = new Map<Id, String>();

        // Nothing to do: avoid firing a SOQL with an empty IN clause.
        if (contactIds == null || contactIds.isEmpty()) {
            return failures;
        }

        // Drop nulls and duplicates so the DML list never contains the same record twice.
        List<Id> uniqueIds = new List<Id>();
        for (Id id : contactIds) {
            if (id != null && !uniqueIds.contains(id)) {
                uniqueIds.add(id);
            }
        }
        if (uniqueIds.isEmpty()) {
            return failures;
        }

        // One SOQL, only the fields we need. Sharing is respected automatically:
        // contacts the caller can't update simply don't come back.
        List<Contact> contactsToUpdate = new List<Contact>();
        for (Contact contact : [SELECT Id, Phone FROM Contact WHERE Id IN :uniqueIds]) {
            if (String.isNotBlank(contact.Phone)) {
                // Keep only digits and '+': "+44 (20) 7946-0018" -> "+442079460018".
                contact.Phone = contact.Phone.replaceAll('[^0-9+]', '');
                contactsToUpdate.add(contact);
            }
        }

        // Contacts without a phone are left out entirely (not updated, not reported).
        if (contactsToUpdate.isEmpty()) {
            return failures;
        }

        // One DML call, allOrNone=false: a record that fails validation
        // doesn't block the rest.
        Database.SaveResult[] results = Database.update(contactsToUpdate, false);

        // Report the Id of every contact that could not be saved with its first error.
        for (Database.SaveResult result : results) {
            if (!result.isSuccess()) {
                failures.put(
                    result.getId(),
                    result.getErrors().isEmpty() ? 'Unknown error' : result.getErrors().get(0).getMessage()
                );
            }
        }

        return failures;
    }
}
