 * so publishing each event individually in the loop is safe at this volume.
 */
public class DealEventPublisher {

    /**
     * Publishes one Deal_Stage_Change__e event per input opportunity.
     *
     * Each event carries:
     *   - Opportunity_Id__c = Opportunity.Id
     *   - Stage__c          = Opportunity.StageName
     *   - Amount__c         = Opportunity.Amount
     *
     * @param opportunities The opportunities to publish events for (from the trigger context).
     * @return One Database.SaveResult per input opportunity, in the same order as the input
     *         list. Returns an empty list (publishes nothing) when the input is null or empty.
     */
    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        List<Database.SaveResult> results = new List<Database.SaveResult>();

        // Nothing to publish for null/empty input.
        if (opportunities == null || opportunities.isEmpty()) {
            return results;
        }

        for (Opportunity opp : opportunities) {
            Deal_Stage_Change__e event = new Deal_Stage_Change__e();
            event.Opportunity_Id__c = opp.Id;
            event.Stage__c          = opp.StageName;
            event.Amount__c         = opp.Amount;

            // Publish one event per opportunity and keep its SaveResult in input order so the
            // caller can identify exactly which opportunity's event failed.
            results.add(EventBus.publish(event));
        }

        return results;
    }
}
