import { generateUniqueId } from 'lightning/uniqueId';

export default class StatusListbox extends LightningElement {
  _label = '';
  _options = [];
  _value = '';
  _activeIndex = 0;
  _prefix = 'status-listbox-' + generateUniqueId();

  get label() {
    return this._label;
  }

  set label(value) {
    this._label = value;
  }

  get options() {
    return this._options;
  }

  set options(value) {
    this._options = Array.isArray(value) ? value : [];
    // Active option is the selected one, or the first option if none is selected.
    this._activeIndex = this._selectedIndex();
  }

  get value() {
    return this._value;
  }

  set value(value) {
    this._value = value;
    // When the parent changes the value, the active option moves to it.
    const index = this._selectedIndex();
    if (index !== -1) {
      this._activeIndex = index;
    }
  }

  _selectedIndex() {
    return this._options.findIndex((option) => option.value === this._value);
  }

  get decoratedOptions() {
    return this._options.map((option, index) => ({
      value: option.value,
      label: option.label,
      id: `${this._prefix}-${index}`,
      selected: option.value === this._value ? 'true' : 'false'
    }));
  }

  get activeId() {
    if (this._activeIndex < 0 || this._activeIndex >= this._options.length) {
      return '';
    }
    return `${this._prefix}-${this._activeIndex}`;
  }

  handleKeydown(event) {
    const count = this._options.length;
    const maxIndex = count - 1;
    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault();
        if (this._activeIndex < maxIndex) {
          this._activeIndex += 1;
        }
        break;
      case 'ArrowUp':
        event.preventDefault();
        if (this._activeIndex > 0) {
          this._activeIndex -= 1;
        }
        break;
      case 'Home':
        event.preventDefault();
        this._activeIndex = 0;
        break;
      case 'End':
        event.preventDefault();
        if (count > 0) {
          this._activeIndex = maxIndex;
        }
        break;
      case 'Enter':
      case ' ':
        event.preventDefault();
        if (this._activeIndex >= 0 && this._activeIndex < count) {
          this.selectOption(this._options[this._activeIndex].value);
        }
        break;
      // Every other key (including Tab) keeps its default behaviour.
    }
  }

  handleOptionClick(event) {
    const value = event.currentTarget.dataset.value;
    this.selectOption(value);
  }

  selectOption(value) {
    const index = this._options.findIndex(
      (option) => String(option.value) === String(value)
    );
    if (index === -1) {
      return;
    }
    // Clicking an option selects it and makes it the active option.
    this._activeIndex = index;
    // Dispatch change only when the selection actually changes.
    if (this._value !== this._options[index].value) {
      this._value = this._options[index].value;
      this.dispatchEvent(
        new CustomEvent('change', { detail: { value: this._value } })
      );
    }
  }
}
