/**
 * Service for recording monthly-giving sign-ups as Enhanced Recurring Donations
 * (npe03__Recurring_Donation__c) in an NPSP org.
 *
 * Installment opportunities are intentionally NOT created here: NPSP's own
 * recurring-donation processing generates them from the schedule on the
 * recurring donation record (driven by npe03__Next_Payment_Date__c and
 * npsp__InstallmentFrequency__c).
 *
 * Bulk-safe: validation is performed in memory before any DML, and the entire
 * batch is persisted with a single DML statement. This service never issues a
 * SOQL query of its own, so 200 requests in one call stay within 0 SOQL / 1 DML.
 */
public class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    /**
     * Creates one Enhanced Recurring Donation per request.
     *
     * @param requests sign-ups from the monthly-giving form.
     * @return the new npe03__Recurring_Donation__c Ids, in request order.
     * @throws RecurringGiftService.RecurringGiftException if any request is
     *         invalid (thrown before any DML) or any record fails to save.
     */
    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return new List<Id>();
        }

        // 1) Validate every request up front so we never write anything when
        //    a request is bad.
        for (Integer i = 0; i < requests.size(); i++) {
            validateRequest(requests.get(i), i);
        }

        // 2) Build one recurring donation per request, preserving request order.
        List<npe03__Recurring_Donation__c> donations = new List<npe03__Recurring_Donation__c>(requests.size());
        for (GiftRequest request : requests) {
            donations.add(buildRecurringDonation(request));
        }

        // 3) A single DML statement for the whole batch.
        List<Database.SaveResult> saveResults = Database.insert(donations, false);

        List<Id> createdIds = new List<Id>(donations.size());
        List<String> errors = new List<String>();
        for (Integer i = 0; i < donations.size(); i++) {
            Database.SaveResult saveResult = saveResults.get(i);
            if (saveResult.isSuccess()) {
                createdIds.add(saveResult.getId());
            } else {
                for (Database.Error error : saveResult.getErrors()) {
                    errors.add('request ' + i + ': ' + error.getStatusCode() + ' ' + error.getMessage());
                }
            }
        }
        if (!errors.isEmpty()) {
            throw new RecurringGiftException('Failed to create recurring gifts. ' + String.join(errors, '; '));
        }
        return createdIds;
    }

    private static void validateRequest(GiftRequest request, Integer index) {
        if (request == null) {
            throw new RecurringGiftException('Invalid request at index ' + index + ': request is null.');
        }
        if (request.contactId == null) {
            throw new RecurringGiftException('Invalid request at index ' + index + ': contactId is required.');
        }
        if (request.amount == null || request.amount <= 0) {
            throw new RecurringGiftException('Invalid request at index ' + index + ': amount must be a positive number.');
        }
        if (request.dayOfMonth == null || request.dayOfMonth < 1 || request.dayOfMonth > 31) {
            throw new RecurringGiftException('Invalid request at index ' + index + ': dayOfMonth must be between 1 and 31.');
        }
        if (request.startDate == null) {
            throw new RecurringGiftException('Invalid request at index ' + index + ': startDate is required.');
        }
    }

    private static npe03__Recurring_Donation__c buildRecurringDonation(GiftRequest request) {
        // Null or 0 installments = open-ended; any positive count = fixed-length.
        Boolean openEnded = (request.installments == null || request.installments <= 0);
        // The form's "31" means "last day of the month": use NPSP's own
        // last-day-of-month option. 29 and 30 are stored as literal days.
        Boolean lastDayOfMonth = (request.dayOfMonth == 31);

        npe03__Recurring_Donation__c rd = new npe03__Recurring_Donation__c();
        rd.npe03__Contact__c = request.contactId;
        rd.npe03__Amount__c = request.amount;

        // Monthly schedule on the given day of the month.
        rd.npe03__Installment_Period__c = '1 month';
        rd.npsp__RecurringType__c = 'Recurring';
        rd.npsp__InstallmentFrequency__c = 'Monthly';
        rd.npsp__Day_of_Month__c = request.dayOfMonth;
        rd.npsp__Always_Use_Last_Day_Of_Month__c = lastDayOfMonth;

        // First installment on startDate. NPSP's recurring-donation process
        // uses Next_Payment_Date to generate the installment opportunities.
        rd.npsp__StartDate__c = request.startDate;
        rd.npe03__Date_Established__c = request.startDate;
        rd.npe03__Next_Payment_Date__c = request.startDate;

        rd.npsp__Status__c = 'Active';
        rd.npsp__PaymentMethod__c = request.paymentMethod;

        if (openEnded) {
            rd.npe03__Schedule_Type__c = 'Open-Ended';
            rd.npe03__Open_Ended_Status__c = 'Active';
        } else {
            rd.npe03__Schedule_Type__c = 'Fixed Number of Installments';
            rd.npe03__Installments__c = request.installments;
            // Last planned installment = start date advanced (installments - 1) months.
            rd.npsp__EndDate__c = request.startDate.addMonths(request.installments - 1);
        }
        return rd;
    }
