/**
 * Service for importing parent/child family links into NPSP.
 *
 * For each (parent, child) pair, creates a single npe4__Relationship__c record of
 * type "Parent" (parent as npe4__Contact__c, child as npe4__RelatedContact__c).
 * Because this org uses NPSP's default "List Settings" reciprocal method, NPSP
 * automatically creates the reciprocal record: the child shows the parent as
 * "Parent" and the parent shows the child as "Son", "Daughter" or "Child"
 * according to the child's gender and the reciprocal lookup.
 *
 * Bulk safe: a call with 200 pairs uses at most 1 SOQL query and 1 DML statement.
 * Idempotent: pairs that already have any relationship between the two contacts
 * (in either direction) are skipped, so the import can be safely re-run.
 */
public class FamilyService {

    private static final String PARENT_TYPE = 'Parent';
    private static final String CURRENT_STATUS = 'Current';
    private static final String DESCRIPTION = 'Parent of child - imported from student system';

    /**
     * Links each child to its parent in NPSP.
     *
     * @param parentIdByChildId child Contact Id (key) -> parent Contact Id (value).
     *                          Null or empty input does nothing.
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Collect the valid parent/child pairs and every contact Id involved.
        Map<Id, Id> parentByChild = new Map<Id, Id>();
        Set<Id> contactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || normalize(childId) == normalize(parentId)) {
                continue; // Not a valid parent/child pair.
            }
            parentByChild.put(childId, parentId);
            contactIds.add(childId);
            contactIds.add(parentId);
        }
        if (parentByChild.isEmpty()) {
            return;
        }

        // Single SOQL query: find any relationship that already exists between the
        // involved contacts, in either direction, so re-runs do not duplicate.
        Set<String> existingPairs = new Set<String>();
        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :contactIds
              AND npe4__RelatedContact__c IN :contactIds
        ]) {
            existingPairs.add(pairKey(rel.npe4__Contact__c, rel.npe4__RelatedContact__c));
        }

        // Build one "Parent" relationship per pair that is not already linked.
        // NPSP's reciprocal processing creates the reciprocal record
        // (Son / Daughter / Child based on the child's gender).
        List<npe4__Relationship__c> newRelationships = new List<npe4__Relationship__c>();
        Set<String> pairsThisBatch = new Set<String>();
        for (Id childId : parentByChild.keySet()) {
            Id parentId = parentByChild.get(childId);
            String pair = pairKey(parentId, childId);
            if (existingPairs.contains(pair) || !pairsThisBatch.add(pair)) {
                continue; // Already linked in the org, or already handled in this batch.
            }
            newRelationships.add(new npe4__Relationship__c(
                npe4__Contact__c = parentId,
                npe4__RelatedContact__c = childId,
                npe4__Type__c = PARENT_TYPE,
                npe4__Status__c = CURRENT_STATUS,
                npe4__Description__c = DESCRIPTION
            ));
        }

        // Single DML statement; NPSP's trigger adds the reciprocal records.
        if (!newRelationships.isEmpty()) {
            insert newRelationships;
        }
    }

    /**
     * Order-independent key for an unordered contact pair.
     */
    private static String pairKey(Id a, Id b) {
        return normalize(a) + '|' + normalize(b);
    }

    /**
     * Normalizes an Id so that the 15- and 18-character forms, and any case
     * difference, compare as the same contact.
     */
    private static String normalize(Id id) {
        return id == null ? '' : id.substring(0, 15).toUpperCase();
    }
}
