/**
 * Trigger Action (TAF 0.3.4) for Account after insert.
 *
 * When a new account is created with Type 'Customer - Direct' or 'Customer - Channel',
 * create an onboarding Task for the account's owner. Accounts of any other type
 * (or with no type) get no task.
 *
 * Bulk-safe: no SOQL, no per-record DML. All qualifying tasks are inserted with a
 * single DML statement per trigger execution, and no DML runs at all when no
 * account qualifies.
 */
public with sharing class TA_Account_CreateOnboardingTask implements TriggerAction.AfterInsert {

    private static final List<String> ELIGIBLE_ACCOUNT_TYPES =
            new List<String> { 'Customer - Direct', 'Customer - Channel' };

    public void afterInsert(List<SObject> triggerNew) {
        List<Task> tasksToInsert = new List<Task>();
        Date activityDate = Date.today().addDays(7);

        for (SObject sObj : triggerNew) {
            Account acc = (Account) sObj;
            if (ELIGIBLE_ACCOUNT_TYPES.contains(acc.Type) && acc.OwnerId != null) {
                tasksToInsert.add(new Task(
                        Subject = 'Onboard new customer',
                        WhatId = acc.Id,
                        OwnerId = acc.OwnerId,
                        ActivityDate = activityDate,
                        Status = 'Not Started',
                        Priority = 'Normal'
                ));
            }
        }

        // Single DML statement per execution; skipped entirely when nothing qualifies.
        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
